from .ranges import parse_range


def _insufficient(length):
    return 416, {
        'Content-Length': '0',
        'Content-Range': f'bytes */{length}',
    }, b''


def serve(data, range_header=None):
    length = len(data)
    if range_header is None:
        return 200, {'Content-Length': str(length)}, data

    parsed = parse_range(range_header)
    if parsed is None:
        return _insufficient(length)

    kind, a, b = parsed

    if kind == 'range':
        start = a
        end = b if b is not None else length - 1
        if end >= length:  # clamp end past EOF
            end = length - 1
        if start >= length or start > end:
            # empty data, start beyond EOF, or reverse bounds
            return _insufficient(length)
        body = data[start:end + 1]
        return 206, {
            'Content-Length': str(len(body)),
            'Content-Range': f'bytes {start}-{end}/{length}',
        }, body

    # suffix: last n bytes
    n = a
    if n == 0 or length == 0:  # zero suffix or empty data
        return _insufficient(length)
    start = length - n
    if start < 0:  # suffix larger than the data
        start = 0
    body = data[start:]
    return 206, {
        'Content-Length': str(len(body)),
        'Content-Range': f'bytes {start}-{length - 1}/{length}',
    }, body
